From 13710c3768001946f7d916e4f2dcb19194752ae2 Mon Sep 17 00:00:00 2001
From: Piotr Wojnarowski <piotr@wojnarow.ski>
Date: Tue, 10 Nov 2026 02:25:54 +0100
Subject: [PATCH 1/2] libtaskmanager: Update active Wayland tasks when
 transient parents change

Track the active Wayland window separately from the task representing it.
Update the represented active task when its transient parent chain changes,
including when the former parent is unmapped.

CCBUG: 527381
---
 libtaskmanager/waylandtasksmodel.cpp | 75 ++++++++++++++++------------
 1 file changed, 43 insertions(+), 32 deletions(-)

diff --git a/libtaskmanager/waylandtasksmodel.cpp b/libtaskmanager/waylandtasksmodel.cpp
index ed0b90cbbf..1c09da7def 100644
--- a/libtaskmanager/waylandtasksmodel.cpp
+++ b/libtaskmanager/waylandtasksmodel.cpp
@@ -445,6 +445,9 @@ public:
     QHash<PlasmaWindow *, AppData> appDataCache;
     QHash<PlasmaWindow *, QDateTime> lastActivated;
     PlasmaWindow *activeWindow = nullptr;
+    PlasmaWindow *focusedWindow = nullptr;
+    // The represented task can disappear while the active window stays mapped.
+    QDateTime focusedWindowLastActivated;
     std::vector<std::unique_ptr<PlasmaWindow>> windows;
     // key=transient child, value=leader
     QHash<PlasmaWindow *, PlasmaWindow *> transients;
@@ -460,6 +463,7 @@ public:
     void initWayland();
     auto findWindow(PlasmaWindow *window) const;
     void addWindow(PlasmaWindow *window);
+    void updateActiveTask();

     const AppData &appData(PlasmaWindow *window);

@@ -524,6 +528,8 @@ void WaylandTasksModel::Private::initWayland()

     QObject::connect(windowManagement.get(), &PlasmaWindowManagement::activeChanged, q, [this] {
         q->beginResetModel();
+        focusedWindow = nullptr;
+        activeWindow = nullptr;
         windows.clear();
         q->endResetModel();
     });
@@ -556,6 +562,11 @@ void WaylandTasksModel::Private::addWindow(PlasmaWindow *window)
     }

     auto removeWindow = [window, this] {
+        if (focusedWindow == window) {
+            focusedWindow = nullptr;
+            updateActiveTask();
+        }
+
         // findWindow() is const, we need a non-const iterator for the "take" below.
         auto it = std::ranges::find_if(windows, [window](const std::unique_ptr<PlasmaWindow> &candidate) {
             return candidate.get() == window;
@@ -616,42 +627,22 @@ void WaylandTasksModel::Private::addWindow(PlasmaWindow *window)
                           QList<int>{Qt::DecorationRole, AppId, AppName, GenericName, LauncherUrl, LauncherUrlWithoutIcon, SkipTaskbar, CanLaunchNewInstance});
     });

-    if (window->windowState & PlasmaWindow::state::state_active) {
-        PlasmaWindow *effectiveActive = window;
-        while (effectiveActive->parentWindow) {
-            effectiveActive = effectiveActive->parentWindow;
-        }
-
-        lastActivated[effectiveActive] = QDateTime::currentDateTime();
-        activeWindow = effectiveActive;
-    }
-
-    QObject::connect(window, &PlasmaWindow::activeChanged, q, [window, this] {
-        const bool active = window->windowState & PlasmaWindow::state::state_active;
-
-        PlasmaWindow *effectiveWindow = window;
-
-        while (effectiveWindow->parentWindow) {
-            effectiveWindow = effectiveWindow->parentWindow;
-        }
-
-        if (active) {
-            lastActivated[effectiveWindow] = QDateTime::currentDateTime();
-
-            if (activeWindow != effectiveWindow) {
-                activeWindow = effectiveWindow;
-                this->dataChanged(effectiveWindow, IsActive);
-            }
-        } else {
-            if (activeWindow == effectiveWindow) {
-                activeWindow = nullptr;
-                this->dataChanged(effectiveWindow, IsActive);
-            }
+    const auto updateActiveWindow = [window, this] {
+        if (window->windowState & PlasmaWindow::state::state_active) {
+            focusedWindow = window;
+            focusedWindowLastActivated = QDateTime::currentDateTime();
+            updateActiveTask();
+        } else if (focusedWindow == window) {
+            focusedWindow = nullptr;
+            updateActiveTask();
         }
-    });
+    };
+    updateActiveWindow();
+    QObject::connect(window, &PlasmaWindow::activeChanged, q, updateActiveWindow);

     QObject::connect(window, &PlasmaWindow::parentWindowChanged, q, [window, this] {
         PlasmaWindow *leader = window->parentWindow.data();
+        updateActiveTask();

         // Migrate demanding attention to new leader.
         if (window->windowState.testFlag(PlasmaWindow::state::state_demands_attention)) {
@@ -850,6 +841,26 @@ QString WaylandTasksModel::Private::groupMimeType()
     return u"windowsystem/multiple-winids+" + uuid.toString();
 }

+void WaylandTasksModel::Private::updateActiveTask()
+{
+    // A change anywhere in the active window's parent chain can change its task.
+    PlasmaWindow *task = focusedWindow;
+    while (task && task->parentWindow) {
+        task = task->parentWindow.data();
+    }
+
+    if (task) {
+        lastActivated[task] = focusedWindowLastActivated;
+    }
+
+    if (activeWindow != task) {
+        PlasmaWindow *oldActiveTask = activeWindow;
+        activeWindow = task;
+        dataChanged(oldActiveTask, IsActive);
+        dataChanged(activeWindow, QList<int>{IsActive, LastActivated});
+    }
+}
+
 void WaylandTasksModel::Private::dataChanged(PlasmaWindow *window, int role)
 {
     auto it = findWindow(window);
