From dc5f0528eaab9fbc969000e847ed908682512dfe Mon Sep 17 00:00:00 2001
From: Piotr Wojnarowski <piotr@wojnarow.ski>
Date: Tue, 10 Nov 2026 02:27:47 +0100
Subject: [PATCH 2/2] libtaskmanager: Test active Wayland transients becoming
 independent

Verify that a focused transient becomes an active independent task when
its parent or an intermediate parent is hidden.
---
 libtaskmanager/autotests/tasksmodeltest.cpp | 77 +++++++++++++++++++++
 1 file changed, 77 insertions(+)

diff --git a/libtaskmanager/autotests/tasksmodeltest.cpp b/libtaskmanager/autotests/tasksmodeltest.cpp
index 4537a566f6..df9f8fcc6f 100644
--- a/libtaskmanager/autotests/tasksmodeltest.cpp
+++ b/libtaskmanager/autotests/tasksmodeltest.cpp
@@ -7,14 +7,18 @@
 #include <QConcatenateTablesProxyModel>
 #include <QPointer>
 #include <QQmlApplicationEngine>
+#include <QRasterWindow>
 #include <QSignalSpy>
 #include <QTest>

+#include <algorithm>
+#include <array>
 #include <memory>

 #include "abstracttasksmodel.h" // For enums
 #include "startuptasksmodel.h"
 #include "tasksmodel.h"
+#include "waylandtasksmodel.h"
 #include "windowtasksmodel.h"

 using namespace Qt::StringLiterals;
@@ -54,6 +58,9 @@ private Q_SLOTS:
      * and are recreated for the next instance.
      */
     void test_sharedModelLifetime();
+
+    void test_activeTransientBecomesIndependent_data();
+    void test_activeTransientBecomesIndependent();
 };

 void TasksModelTest::initTestCase()
@@ -276,6 +283,76 @@ void TasksModelTest::test_sharedModelLifetime()
     QTRY_VERIFY(containsWindow(recreatedModel));
 }

+void TasksModelTest::test_activeTransientBecomesIndependent_data()
+{
+    QTest::addColumn<int>("transientDepth");
+    QTest::newRow("parent") << 1;
+    QTest::newRow("ancestor") << 2;
+}
+
+void TasksModelTest::test_activeTransientBecomesIndependent()
+{
+    QFETCH(int, transientDepth);
+
+    WaylandTasksModel windows;
+    TasksModel tasks;
+    tasks.setGroupMode(TasksModel::GroupDisabled);
+    const auto findWindow = [&windows](const QWindow &window) {
+        return windows.match(windows.index(0, 0), Qt::DisplayRole, window.title()).value(0);
+    };
+
+    std::array<QRasterWindow, 3> chain;
+    for (int i = 0; i <= transientDepth; ++i) {
+        auto &window = chain[i];
+        window.setTitle(u"__testwindow__transient_%1__"_s.arg(i));
+        window.resize(200, 200);
+        window.setTransientParent(i > 0 ? &chain[i - 1] : nullptr);
+        window.show();
+        QTRY_VERIFY(findWindow(window).isValid());
+    }
+
+    auto &first = chain.front();
+    auto &parent = chain[transientDepth - 1];
+    auto &child = chain[transientDepth];
+    const QPersistentModelIndex firstIndex = findWindow(first);
+    const QPersistentModelIndex parentIndex = findWindow(parent);
+    const QPersistentModelIndex childIndex = findWindow(child);
+    QTRY_VERIFY(child.isActive());
+    QTRY_VERIFY(firstIndex.data(AbstractTasksModel::IsActive).toBool());
+    QTRY_COMPARE(tasks.activeTask().data().toString(), first.title());
+    const auto lastActivated = firstIndex.data(AbstractTasksModel::LastActivated).toDateTime();
+    QVERIFY(lastActivated.isValid());
+
+    QSignalSpy focusChangedSpy(qGuiApp, &QGuiApplication::focusWindowChanged);
+    QSignalSpy dataChangedSpy(&windows, &QAbstractItemModel::dataChanged);
+    const auto notified = [&dataChangedSpy](const QModelIndex &index, int role) {
+        return std::ranges::any_of(dataChangedSpy, [&index, role](const QList<QVariant> &change) {
+            return change.at(0).value<QModelIndex>() == index && change.at(2).value<QList<int>>().contains(role);
+        });
+    };
+    const auto windowIds = childIndex.data(AbstractTasksModel::WinIdList);
+
+    // Hiding the immediate parent leaves the focused child mapped and independent.
+    // With a nested transient, the former active leader stays in the model as well.
+    parent.hide();
+    QTRY_VERIFY(!parentIndex.isValid());
+    QTRY_VERIFY(!childIndex.data(AbstractTasksModel::SkipTaskbar).toBool());
+    QTRY_VERIFY(childIndex.data(AbstractTasksModel::IsActive).toBool());
+    QCOMPARE(childIndex.data(AbstractTasksModel::WinIdList), windowIds);
+    QCOMPARE(childIndex.data(AbstractTasksModel::LastActivated).toDateTime(), lastActivated);
+    QTRY_COMPARE(tasks.activeTask().data().toString(), child.title());
+    QVERIFY(notified(childIndex, AbstractTasksModel::IsActive));
+    QVERIFY(notified(childIndex, AbstractTasksModel::LastActivated));
+    if (transientDepth > 1) {
+        QVERIFY(firstIndex.isValid());
+        QVERIFY(!firstIndex.data(AbstractTasksModel::IsActive).toBool());
+        QVERIFY(notified(firstIndex, AbstractTasksModel::IsActive));
+    }
+    QCOMPARE(qGuiApp->focusWindow(), &child);
+    QVERIFY(child.isActive());
+    QVERIFY(focusChangedSpy.isEmpty());
+}
+
 QTEST_MAIN(TasksModelTest)

 #include "tasksmodeltest.moc"
